// Dibuat otomatis: gambar layar asli aplikasi Sinau (base64)
const IMAGES = {"a01_login": "", "a02_daftar": "", "a03_lupa": "", "b01_dasbor": "", "b02_dasbor_unit": "", "b03_materi": "", "b04_editor": "", "b05_soal": "", "b06_anggota": "", "b07_masukan": "", "b08_informasi": "", "b09_tambah_info": "", "b10_profil": "", "u01_belajar": "", "u02_beranda": "", "u03_tugas": "", "u04_materi": "", "u05_soal": "", "u06_informasi": "", "u07_peringkat": "", "u08_profil": "", "u09_profil_bawah": "", "u10_masukan": "", "u11_foto": "", "u12_dialog": "", "z_dialog": ""};

// ===== Sinau — pembuat prototipe Figma =====
// Membuat semua layar (gambar asli aplikasi), area klik (hotspot), dan flow User & Admin.
const W = 375, H = 812, GAP = 80, LABEL = 36;

async function run() {
  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  await figma.loadFontAsync({ family: "Inter", style: "Bold" });

  const page = figma.createPage();
  page.name = "Prototipe Sinau";
  await figma.setCurrentPageAsync(page);

  const img = (key) => figma.createImage(figma.base64Decode(IMAGES[key])).hash;
  const frames = {};

  function text(str, x, y, size, bold, color) {
    const t = figma.createText();
    t.fontName = { family: "Inter", style: bold ? "Bold" : "Regular" };
    t.characters = str;
    t.fontSize = size;
    t.fills = [{ type: "SOLID", color: color || { r: 0.09, g: 0.1, b: 0.17 } }];
    t.x = x; t.y = y;
    page.appendChild(t);
    return t;
  }

  function screen(id, name, imageKey, col, row) {
    const f = figma.createFrame();
    f.name = name;
    f.resize(W, H);
    f.x = col * (W + GAP);
    f.y = row * (H + LABEL + 220) + LABEL + 120;
    f.fills = [{ type: "IMAGE", imageHash: img(imageKey), scaleMode: "FILL" }];
    f.clipsContent = true;
    page.appendChild(f);
    text(name, f.x, f.y - LABEL, 18, true);
    frames[id] = f;
    return f;
  }

  // ---------- Judul ----------
  text("Prototipe Sinau", 0, -260, 56, true, { r: 0.26, g: 0.22, b: 0.79 });
  text("Kelompok 4 · UAS Praktikum Mobile Programming · Desain mengikuti aplikasi Flutter Sinau", 0, -180, 22, false);
  text("Tekan Present (▶) lalu pilih flow “User” atau “Admin”. Keluar → konfirmasi → kembali ke halaman Masuk.", 0, -140, 18, false, { r: 0.29, g: 0.31, b: 0.4 });

  // ---------- Baris 0: User ----------
  text("USER", 0, 40, 28, true, { r: 0.26, g: 0.22, b: 0.79 });
  const U = [
    ["loginU", "Masuk (User)", "a01_login"], ["daftar", "Daftar", "a02_daftar"], ["lupa", "Lupa kata sandi", "a03_lupa"],
    ["belajar", "Belajar · Pilih bahasa", "u01_belajar"], ["beranda", "Beranda Python", "u02_beranda"], ["tugas", "Tugas 1 · Pembahasan", "u03_tugas"],
    ["materi", "Materi", "u04_materi"], ["soal", "Soal tugas", "u05_soal"], ["infoU", "Informasi", "u06_informasi"],
    ["rank", "Peringkat", "u07_peringkat"], ["profilU", "Profil", "u08_profil"], ["profilU2", "Profil (bawah)", "u09_profil_bawah"],
    ["dialogU", "Konfirmasi keluar (User)", "u12_dialog"], ["masukanU", "Kirim masukan", "u10_masukan"], ["fotoU", "Foto profil", "u11_foto"],
  ];
  U.forEach(([id, name, key], i) => screen(id, name, key, i, 0));

  // ---------- Baris 1: Admin ----------
  const rowAdminY = 1 * (H + LABEL + 220) + 40;
  text("ADMIN", 0, rowAdminY, 28, true, { r: 0.09, g: 0.1, b: 0.17 });
  const A = [
    ["loginA", "Masuk (Admin)", "a01_login"], ["dasbor", "Dasbor", "b01_dasbor"], ["dasbor2", "Dasbor · Kemampuan per tugas", "b02_dasbor_unit"],
    ["materiA", "Kelola materi", "b03_materi"], ["editor", "Ubah pembahasan", "b04_editor"], ["editor2", "Ubah pembahasan · Soal", "b05_soal"],
    ["anggota", "Anggota", "b06_anggota"], ["masukanA", "Masukan pengguna", "b07_masukan"], ["infoA", "Kelola informasi", "b08_informasi"],
    ["tambahInfo", "Tambah informasi", "b09_tambah_info"], ["profilA", "Profil admin", "b10_profil"], ["dialogA", "Konfirmasi keluar (Admin)", "b10_profil"],
  ];
  A.forEach(([id, name, key], i) => screen(id, name, key, i, 1));

  // Dialog admin = profil admin + layar gelap + kotak dialog
  const dim = figma.createRectangle();
  dim.resize(W, H);
  dim.fills = [{ type: "SOLID", color: { r: 0.09, g: 0.1, b: 0.17 }, opacity: 0.45 }];
  dim.name = "Latar gelap";
  frames.dialogA.appendChild(dim);
  const box = figma.createRectangle();
  box.resize(295, 226); box.x = 40; box.y = 293; box.name = "Dialog keluar";
  box.fills = [{ type: "IMAGE", imageHash: img("z_dialog"), scaleMode: "FILL" }];
  box.cornerRadius = 28;
  frames.dialogA.appendChild(box);

  // ---------- Hotspot ----------
  const pending = [];
  function hot(frameId, name, x, y, w, h, dest) {
    const r = figma.createRectangle();
    r.name = "Klik: " + name;
    r.resize(w, h); r.x = x; r.y = y;
    r.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 }, opacity: 0 }];
    frames[frameId].appendChild(r);
    const action = dest === "BACK"
      ? { type: "BACK" }
      : { type: "NODE", destinationId: frames[dest].id, navigation: "NAVIGATE",
          transition: { type: "DISSOLVE", easing: { type: "EASE_OUT" }, duration: 0.2 },
          preserveScrollPosition: false, resetScrollPosition: true };
    pending.push([r, [{ trigger: { type: "ON_CLICK" }, actions: [action] }]]);
  }

  // Masuk / daftar / lupa
  for (const [login, home] of [["loginU", "belajar"], ["loginA", "dasbor"]]) {
    hot(login, "Masuk", 24, 485, 327, 52, home);
    hot(login, "Lupa kata sandi", 225, 438, 125, 30, "lupa");
    hot(login, "Daftar", 228, 553, 55, 26, "daftar");
  }
  hot("daftar", "Tutup", 326, 18, 36, 36, "BACK");
  hot("daftar", "Buat akun", 24, 558, 327, 52, "belajar");
  hot("lupa", "Tutup", 326, 18, 36, 36, "BACK");

  // Menu bawah user + tombol masukan
  const userTabs = ["belajar", "infoU", "rank", "profilU", "profilU2"];
  for (const f of userTabs) {
    hot(f, "Tab Belajar", 0, 748, 94, 64, "belajar");
    hot(f, "Tab Informasi", 94, 748, 93, 64, "infoU");
    hot(f, "Tab Peringkat", 187, 748, 94, 64, "rank");
    hot(f, "Tab Profil", 281, 748, 94, 64, "profilU");
    hot(f, "Ada saran atau error?", 158, 675, 201, 56, "masukanU");
  }

  // Alur belajar
  hot("belajar", "Python", 20, 156, 335, 170, "beranda");
  hot("belajar", "Java", 20, 340, 335, 170, "beranda");
  hot("beranda", "Kembali", 22, 16, 36, 36, "belajar");
  hot("beranda", "Ganti bahasa", 252, 314, 100, 26, "belajar");
  hot("beranda", "Mulai (lanjutkan)", 249, 214, 89, 40, "materi");
  hot("beranda", "Tugas 1", 20, 377, 335, 113, "tugas");
  hot("tugas", "Kembali", 14, 22, 36, 36, "beranda");
  hot("tugas", "Pembahasan 1", 20, 236, 335, 82, "materi");
  hot("materi", "Tutup", 14, 14, 36, 36, "tugas");
  hot("materi", "Kerjakan tugas", 20, 740, 335, 52, "soal");
  hot("soal", "Tutup", 14, 14, 36, 36, "tugas");
  hot("soal", "Lanjut", 20, 740, 335, 52, "tugas");

  // Profil, foto, masukan, keluar
  hot("profilU", "Ganti foto", 203, 143, 36, 36, "fotoU");
  hot("profilU", "Gulir ke bawah", 20, 287, 335, 360, "profilU2");
  hot("profilU2", "Gulir ke atas", 20, 80, 335, 220, "profilU");
  hot("profilU2", "Keluar", 20, 566, 335, 52, "dialogU");
  hot("dialogU", "Batal", 178, 452, 60, 36, "profilU2");
  hot("dialogU", "Keluar → Masuk", 248, 452, 64, 36, "loginU");
  hot("masukanU", "Tutup (area gelap)", 0, 0, 375, 370, "BACK");
  hot("masukanU", "Kirim", 20, 740, 335, 52, "BACK");
  hot("fotoU", "Tutup (area gelap)", 0, 0, 375, 545, "BACK");

  // Menu bawah admin + tombol profil (perisai)
  const adminTabs = ["dasbor", "dasbor2", "materiA", "anggota", "masukanA", "infoA"];
  for (const f of adminTabs) {
    hot(f, "Tab Dasbor", 0, 748, 75, 64, "dasbor");
    hot(f, "Tab Materi", 75, 748, 75, 64, "materiA");
    hot(f, "Tab Anggota", 150, 748, 75, 64, "anggota");
    hot(f, "Tab Masukan", 225, 748, 75, 64, "masukanA");
    hot(f, "Tab Informasi", 300, 748, 75, 64, "infoA");
    if (f !== "infoA") hot(f, "Profil admin", 309, 22, 40, 40, "profilA");
  }
  hot("dasbor", "Gulir ke bawah", 20, 500, 335, 240, "dasbor2");
  hot("dasbor2", "Gulir ke atas", 20, 80, 335, 170, "dasbor");
  hot("materiA", "Ubah pembahasan", 20, 284, 200, 56, "editor");
  hot("editor", "Kembali", 14, 22, 36, 36, "materiA");
  hot("editor", "Gulir ke soal", 20, 360, 335, 440, "editor2");
  hot("editor2", "Kembali", 14, 22, 36, 36, "materiA");
  hot("editor2", "Gulir ke atas", 20, 80, 335, 120, "editor");
  hot("infoA", "Tambah", 227, 19, 128, 42, "tambahInfo");
  hot("tambahInfo", "Tutup (area gelap)", 0, 0, 375, 300, "BACK");
  hot("tambahInfo", "Kirim", 20, 740, 335, 52, "BACK");
  hot("profilA", "Kembali", 14, 22, 36, 36, "dasbor");
  hot("profilA", "Keluar", 20, 538, 335, 52, "dialogA");
  hot("dialogA", "Batal", 178, 452, 60, 36, "profilA");
  hot("dialogA", "Keluar → Masuk", 248, 452, 64, 36, "loginA");

  for (const [node, reactions] of pending) {
    if (typeof node.setReactionsAsync === "function") await node.setReactionsAsync(reactions);
    else node.reactions = reactions;
  }

  page.flowStartingPoints = [
    { nodeId: frames.loginU.id, name: "User" },
    { nodeId: frames.loginA.id, name: "Admin" },
  ];
  figma.viewport.scrollAndZoomIntoView(Object.values(frames));
  return { screens: Object.keys(frames).length, hotspots: pending.length };
}

run()
  .then((r) => figma.closePlugin(`Prototipe Sinau dibuat: ${r.screens} layar, ${r.hotspots} area klik.`))
  .catch((e) => figma.closePlugin("Gagal: " + (e && e.message ? e.message : e)));
